// Build-time Markdown mirrors of the HTML pages, for agents that send "Accept: text/markdown".
// Every indexable page gets a file in <out>/md/ (/ -> md/index.md, /services/ -> md/services.md).
// middleware.js serves those files when a request prefers Markdown. Generated: do not edit by hand.
import fs from "node:fs";
import path from "node:path";
import TurndownService from "turndown";
import { PUBLIC, writeFile } from "./util.js";

const SKIP_TOP = new Set(["md", "assets", "api"]);

/** URL path ("/services/") -> Markdown file path inside md/ ("services.md"). */
export function markdownPathFor(urlPath) {
  const clean = urlPath.replace(/^\/+|\/+$/g, "");
  return clean ? `${clean}.md` : "index.md";
}

function decode(s) {
  return s
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
}

function pick(html, re) {
  const m = html.match(re);
  return m ? decode(m[1].replace(/\s+/g, " ").trim()) : "";
}

function makeConverter(siteUrl) {
  const td = new TurndownService({ headingStyle: "atx", bulletListMarker: "-", codeBlockStyle: "fenced", linkStyle: "inlined" });
  td.remove(["script", "style", "noscript", "svg", "iframe", "video", "audio", "form", "button", "nav", "header", "footer", "template", "select", "input", "textarea"]);
  td.addRule("absoluteLinks", {
    filter: (node) => node.nodeName === "A" && node.getAttribute("href"),
    replacement: (content, node) => {
      const text = content.replace(/\s+/g, " ").trim();
      if (!text) return "";
      let href = node.getAttribute("href").trim();
      if (href.startsWith("#") || /^(javascript:|tel:)/i.test(href)) return text;
      if (href.startsWith("/") && !href.startsWith("//")) href = siteUrl + href;
      return `[${text}](${href})`;
    },
  });
  td.addRule("dropImages", { filter: "img", replacement: (_c, node) => (node.getAttribute("alt") || "").trim() });
  return td;
}

/** Convert one rendered HTML page to a Markdown document. */
export function htmlToMarkdown(html, { siteUrl, urlPath }) {
  const title = pick(html, /<title[^>]*>([\s\S]*?)<\/title>/i);
  const description = pick(html, /<meta\s+name=["']description["']\s+content=["']([^"']*)["']/i)
    || pick(html, /<meta\s+content=["']([^"']*)["']\s+name=["']description["']/i);
  const body = (html.match(/<main[\s\S]*<\/main>/i) || html.match(/<body[\s\S]*<\/body>/i) || [html])[0];
  let md = makeConverter(siteUrl).turndown(body)
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  if (!/^#\s/m.test(md) && title) md = `# ${title}\n\n${md}`;
  const lines = [md, "", "---", ""];
  lines.unshift(`<!-- Markdown version of ${siteUrl}${urlPath}. Generated by scripts/build.js. Do not edit by hand. -->`, "");
  if (description && !md.includes(description)) lines.splice(2, 0, `> ${description}`, "");
  lines.push(`Source: ${siteUrl}${urlPath}`, `Site index for agents: ${siteUrl}/llms.txt`, "");
  return lines.join("\n");
}

function* walk(dir, skip, rel = "") {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) {
      if (!rel && (SKIP_TOP.has(e.name) || skip.has(e.name) || e.name.startsWith("."))) continue;
      if (e.name === "images") continue;
      yield* walk(path.join(dir, e.name), skip, r);
    } else if (e.name === "index.html") {
      yield r;
    }
  }
}

/** Rebuild <out>/md from every indexable index.html under <out>. Returns the URL paths written. */
export function buildMarkdownMirror(out, site) {
  const mdDir = path.join(out, "md");
  fs.rmSync(mdDir, { recursive: true, force: true });
  // Pages in <out> win. When building somewhere other than public/ (dev preview), hand-written pages still live in public/.
  const sources = new Map();
  if (path.resolve(out) !== path.resolve(PUBLIC)) {
    for (const f of walk(PUBLIC, new Set(["blog"]))) sources.set(f, path.join(PUBLIC, f));
  }
  for (const f of walk(out, new Set())) sources.set(f, path.join(out, f));
  const written = [];
  for (const [f, file] of sources) {
    const html = fs.readFileSync(file, "utf8");
    if (/<meta[^>]+name=["']robots["'][^>]+noindex/i.test(html)) continue;
    const dirPart = path.posix.dirname(f.replace(/\\/g, "/"));
    const urlPath = dirPart === "." ? "/" : `/${dirPart}/`;
    writeFile(path.join(mdDir, markdownPathFor(urlPath)), htmlToMarkdown(html, { siteUrl: site.site_url, urlPath }));
    written.push(urlPath);
  }
  return written;
}
